results.final_sql:
SELECT AVG(
  CAST(
    SUBSTR(r.fastestLapTime, 1, 1) AS REAL
  ) * 60 +
  CAST(
    SUBSTR(r.fastestLapTime, 3, 2) AS REAL
  ) +
  CAST(
    SUBSTR(r.fastestLapTime, 6, 5) AS REAL
  ) / 1000
) AS average_fastest_lap_time_seconds
FROM results r
JOIN drivers d ON r.driverId = d.driverId
WHERE d.forename = 'Lewis' AND d.surname = 'Hamilton'
  AND r.fastestLapTime IS NOT NULL;

SELECT 
  (SELECT COALESCE(SUM(b.spent), 0) FROM budget b JOIN event e ON b.link_to_event = e.event_id WHERE strftime('%Y', e.event_date) = '2020') -
  (SELECT COALESCE(SUM(b.spent), 0) FROM budget b JOIN event e ON b.link_to_event = e.event_id WHERE strftime('%Y', e.event_date) = '2019') AS difference;
